// e2e/admin/titles.spec.ts
import { test, expect } from '@playwright/test';
import { loginAs } from '../fixtures/auth';

test.describe('Admin Title Management', () => {
  test.beforeEach(async ({ page }) => {
    await loginAs(page, 'admin');
    await page.goto('/admin/titles');
  });

  test('should create a new title', async ({ page }) => {
    await page.click('[data-testid="create-title-btn"]');

    await page.fill('[name="title"]', 'Test Capstone Title');
    await page.fill('[name="description"]', 'This is a test description for the capstone project');
    await page.selectOption('[name="periodId"]', '1');
    await page.fill('[name="quota"]', '5');

    await page.click('[data-testid="submit-title-btn"]');

    await expect(page.locator('[data-testid="success-toast"]')).toBeVisible();
    await expect(page.locator('text=Test Capstone Title')).toBeVisible();
  });

  test('should edit an existing title', async ({ page }) => {
    await page.click('[data-testid="edit-title-btn"]:first-of-type');

    await page.fill('[name="title"]', 'Updated Title Name');
    await page.click('[data-testid="submit-title-btn"]');

    await expect(page.locator('[data-testid="success-toast"]')).toBeVisible();
    await expect(page.locator('text=Updated Title Name')).toBeVisible();
  });

  test('should delete a title', async ({ page }) => {
    const titleName = await page.locator('[data-testid="title-row"]:first-of-type td:first-child').textContent();

    await page.click('[data-testid="delete-title-btn"]:first-of-type');
    await page.click('[data-testid="confirm-delete-btn"]');

    await expect(page.locator('[data-testid="success-toast"]')).toBeVisible();
    await expect(page.locator(`text=${titleName}`)).not.toBeVisible();
  });

  test('should search titles', async ({ page }) => {
    await page.fill('[data-testid="search-input"]', 'Test');
    await page.keyboard.press('Enter');

    await expect(page.locator('[data-testid="title-row"]')).toHaveCount(1);
  });
});
